components.example:
if breeze.AlertDialog(c, &app.confirm, "Delete?", "This cannot be undone.", "Delete", "Cancel") == 0 {
	app.delete()
}

breeze.GridView(c, &app.photos, len(app.thumbs), 140, 120, func(i int) {
	ui.Image(c, app.thumbs[i])
})

breeze.HeaderBar(c, "Documents", "12 items", func() {
	breeze.BackButton(c, app.router)
}, func() {
	breeze.IconButton(c, shareIcon, "Share")
})

breeze.List(c, &app.files, len(app.names), func(i int) {
	ui.Text(c, app.names[i])
})

breeze.Outline(c, &app.files, roots, children, func(path string) {
	ui.Text(c, path)
})

breeze.OutlineTable(c, &app.files, columns, roots, children, func(path string, col int) {
	ui.Text(c, path)
})

breeze.PreferencesGroup(c, "Storage", "Uploads go to the default.", func() {
	breeze.Button(c, "Add")
}, func() {
	breeze.ActionRow(c, "R2", "Default", nil)
})

breeze.PrefixRow(c, "Whisper", "Base · 142 MB", func() {
	ui.Icon(c, app.modelIcon)
}, func() {
	breeze.Button(c, "Remove")
})

breeze.Scroll(c).Grow(1).Children(func() {
	for _, line := range app.lines {
		ui.Text(c, line)
	}
})

breeze.ScrollHorizontal(c).Gap(8).Children(func() {
	for _, tag := range app.tags {
		breeze.Button(c, tag)
	}
})

breeze.Sidebar(c, &app.mailbox, func() {
	breeze.SidebarSection(c, "Mailboxes", &app.mailboxes, func() {
		breeze.SidebarItem(c, "inbox", inboxIcon, "Inbox")
	})
}).Width(220)

breeze.StatusPage(c, searchIcon, "No Results", "Check the spelling or try a new search.", func() {
	breeze.Button(c, "Clear Search")
})

breeze.TabView(c, &app.tab, app.titles, func(i int) {
	app.titles = slices.Delete(app.titles, i, i+1)
}, func() {
	app.titles = append(app.titles, "Untitled")
	app.tab = len(app.titles) - 1
})

breeze.Table(c, &app.list, columns, len(app.rows), func(row, col int) {
	ui.Text(c, app.rows[row][col])
})

breeze.Toolbar(c, func() {
	breeze.BackButton(c, app.router)
	ui.Spacer(c)
	breeze.Button(c, "Share")
}).Label("Actions")
